section('R5 voice: server-sent events from the API');
$sse = "event: message_start\ndata: " . json_encode(['type' => 'message_start', 'message' => ['id' => 'msg_1', 'model' => 'claude-sonnet-5-5', 'usage' => ['input_tokens' => 100, 'cache_read_input_tokens' => 20, 'output_tokens' => 1]]]) . "\n\n"
    . "event: ping\ndata: {\"type\": \"ping\"}\n\n" . "event: content_block_start\ndata: " . json_encode(['type' => 'content_block_start', 'index' => 0, 'content_block' => ['type' => 'text', 'text' => '']]) . "\n\n"
    . "event: content_block_delta\ndata: " . json_encode(['type' => 'content_block_delta', 'index' => 0, 'delta' => ['type' => 'text_delta', 'text' => 'Hello ₹']]) . "\n\n" . "event: content_block_delta\ndata: " . json_encode(['type' => 'content_block_delta', 'index' => 0, 'delta' => ['type' => 'text_delta', 'text' => '5,000. Bye.']]) . "\n\n"
    . "event: content_block_stop\ndata: {\"type\":\"content_block_stop\",\"index\":0}\n\n" . "event: content_block_start\ndata: " . json_encode(['type' => 'content_block_start', 'index' => 1, 'content_block' => ['type' => 'tool_use', 'id' => 'toolu_9', 'name' => 'list_goals', 'input' => new stdClass()]]) . "\n\n"
    . "event: content_block_delta\ndata: " . json_encode(['type' => 'content_block_delta', 'index' => 1, 'delta' => ['type' => 'input_json_delta', 'partial_json' => '{"limit":']]) . "\n\n" . "event: content_block_delta\ndata: " . json_encode(['type' => 'content_block_delta', 'index' => 1, 'delta' => ['type' => 'input_json_delta', 'partial_json' => '3}']]) . "\n\n"
    . "event: content_block_stop\ndata: {\"type\":\"content_block_stop\",\"index\":1}\n\n" . "event: message_delta\ndata: " . json_encode(['type' => 'message_delta', 'delta' => ['stop_reason' => 'tool_use'], 'usage' => ['output_tokens' => 33]]) . "\n\n" . "event: message_stop\ndata: {\"type\":\"message_stop\"}\n\n";
$st = ai_sse_new(); $got = []; ai_sse_feed($st, $sse, function ($t) use (&$got) { $got[] = $t; }); $msg = ai_sse_message($st);
eq($got, ['Hello ₹', '5,000. Bye.'], 'text deltas are passed on as they come'); eq($msg['content'][0]['text'], 'Hello ₹5,000. Bye.', 'and assembled into the block'); eq($msg['content'][1]['input'], ['limit' => 3], 'tool input JSON is assembled from its fragments'); eq($msg['stop_reason'], 'tool_use', 'stop reason'); eq($msg['usage']['output_tokens'], 33, 'usage: output tokens from message_delta'); eq($msg['usage']['input_tokens'], 100, 'usage: input tokens from message_start'); eq($st['done'], true, 'message_stop seen');
$st2 = ai_sse_new(); $got2 = []; foreach (str_split($sse, 7) as $piece) { ai_sse_feed($st2, $piece, function ($t) use (&$got2) { $got2[] = $t; }); } eq(ai_sse_message($st2), $msg, 'the same result when the bytes arrive in 7-byte pieces (events split anywhere)'); eq(implode('', $got2), implode('', $got), 'and the same text');
$st3 = ai_sse_new(); ai_sse_feed($st3, "event: error\ndata: {\"type\":\"error\",\"error\":{\"type\":\"overloaded_error\",\"message\":\"Overloaded\"}}\n\n"); eq($st3['error']['type'], 'overloaded_error', 'an error event is recorded'); $st4 = ai_sse_new(); ai_sse_feed($st4, "data: not json\n\ndata: [DONE]\n\n\r\n"); eq($st4['blocks'], [], 'garbage lines are ignored');
$st5 = ai_sse_new(); ai_sse_feed($st5, str_replace("\n", "\r\n", $sse)); eq(ai_sse_message($st5)['content'][0]['text'], 'Hello ₹5,000. Bye.', 'CRLF line endings work too');
