if ($up) {
    putenv('MFNC_AI_MOCK=0'); putenv('ANTHROPIC_API_KEY=test-key'); putenv('MFNC_AI_BASE=http://127.0.0.1:8095'); $pcs = []; $tm = [];
    $body = ['model' => 'claude-sonnet-5-5', 'max_tokens' => 200, 'messages' => [['role' => 'user', 'content' => 'hello']]];
    $r = ai_http($body, function ($t) use (&$pcs, &$tm) { $pcs[] = $t; $tm[] = microtime(true); });
    eq($pcs, ['Hello', ' there. This is ', 'the second sentence', '. And a third one.'], 'deltas arrive piece by piece'); check('...really incrementally (the server pauses between pieces)', count($tm) === 4 && ($tm[3] - $tm[0]) > 0.12, round(($tm[3] ?? 0) - ($tm[0] ?? 0), 3) . 's');
    eq($r['content'][0]['text'], 'Hello there. This is the second sentence. And a third one.', 'the finished message has the whole text'); eq($r['usage']['output_tokens'], 22, 'usage reaches the caller'); eq($r['stop_reason'], 'end_turn', 'stop reason');
    $seen = json_decode((string) file_get_contents(sys_get_temp_dir() . '/mfnc_sse_mock_last.json'), true); eq($seen['stream'], true, 'the request asked for a stream'); eq($seen['accept'], 'text/event-stream', 'with the event-stream accept header'); eq($seen['key'], 'test-key', 'and the key');
    $rt = ai_http(['messages' => [['role' => 'user', 'content' => 'tool please']]] + $body, fn($t) => null); eq($rt['content'][1]['type'], 'tool_use', 'a streamed tool call'); eq($rt['content'][1]['input'], ['scope' => 'all'], 'with its input assembled'); eq($rt['stop_reason'], 'tool_use', 'and the right stop reason');
    $rc = ai_http(['messages' => [['role' => 'user', 'content' => 'cut it']]] + $body, fn($t) => null); eq($rc['content'][0]['text'], 'Hello there. This is the second sentence. And a third one.', 'a stream that is cut keeps what arrived');
    $eu = null; try { ai_http(['messages' => [['role' => 'user', 'content' => 'error400']]] + $body, fn($t) => null); } catch (UserError $e) { $eu = $e; } check('an HTTP error takes the normal error path (a friendly UserError)', $eu instanceof UserError);
    // a whole voice turn over the real transport
    $vu2 = $R5('r5stream@x.test'); $vu2u = $R5u($vu2); run("UPDATE {ai_profiles} SET stage='ready', agent_name='Paisa' WHERE user_id=?", [ai_profile($vu2) ? $vu2 : $vu2]); set_setting('ai_enabled', '1'); set_setting('feat_ai_mode', 'free'); $evs = []; $emit2 = function ($e) use (&$evs) { $evs[] = $e; };
    ai_turn($vu2u, 'hello voice', $emit2, ['voice' => true, 'stream' => true, 'stt' => 'browser']); $dl = array_values(array_filter($evs, fn($e) => $e['type'] === 'delta')); check('streamed voice turn: delta events came first, then the final block', count($dl) === 4 && array_search('delta', array_column($evs, 'type')) < array_search('block', array_column($evs, 'type')));
    eq(implode('', array_column($dl, 'text')), 'Hello there. This is the second sentence. And a third one.', 'the deltas add up to the stored reply'); $ur = one('SELECT input_tokens,output_tokens FROM {ai_usage} WHERE user_id=? ORDER BY id DESC LIMIT 1', [$vu2]); eq([(int) $ur['input_tokens'], (int) $ur['output_tokens']], [150, 22], 'AI tokens (input + cache) are metered through ai_record_usage');
    putenv('MFNC_AI_BASE'); putenv('ANTHROPIC_API_KEY'); putenv('MFNC_AI_MOCK=1');
