section('R5 voice: a spoken turn through the chat engine (mock transport)');
$vu = $R5('r5voice@x.test', 'Voice Tester'); $vuu = $R5u($vu, 'user', 'Voice Tester'); putenv('MFNC_AI_MOCK=1'); set_setting('ai_enabled', '1'); set_setting('feat_ai_mode', 'free'); ai_profile($vu); run("UPDATE {ai_profiles} SET stage='ready', agent_name='Paisa' WHERE user_id=?", [$vu]);
$evs = []; $emit = function ($e) use (&$evs) { $evs[] = $e; }; $n0 = (int) val('SELECT COUNT(*) FROM {ai_messages} WHERE user_id=?', [$vu]);
ai_turn($vuu, 'how am I doing with my bills', $emit, ['voice' => true, 'stream' => true, 'stt' => 'elevenlabs']); $types = array_column($evs, 'type');
check('a voice turn streams live text, then the finished block, then done', in_array('delta', $types, true) && in_array('block', $types, true) && end($types) === 'done' && array_search('delta', $types) < array_search('block', $types));
$deltaText = implode('', array_column(array_filter($evs, fn($e) => $e['type'] === 'delta'), 'text')); $blockText = ''; foreach ($evs as $e) { if ($e['type'] === 'block' && ($e['block']['type'] ?? '') === 'text') { $blockText .= $e['block']['text']; } }
check('live text equals the stored text of the last step', $deltaText !== '' && str_contains($blockText, trim($deltaText)) || str_contains($deltaText, trim($blockText))); check('events carry the step number (so the browser can match live text to its block)', isset($evs[array_search('delta', $types)]['step']) && isset($evs[array_search('block', $types)]['step']));
$rows = all('SELECT role,content FROM {ai_messages} WHERE user_id=? ORDER BY id', [$vu]); eq(count($rows), $n0 + 2, 'two messages were stored: what was said and the reply'); $cu = json_decode($rows[$n0]['content'], true); $ca = json_decode($rows[$n0 + 1]['content'], true);
eq([$cu['voice'], $cu['stt'], $cu['text']], [1, 'elevenlabs', 'how am I doing with my bills'], 'the transcript is stored with the voice flag and how it was transcribed'); eq($ca['voice'], 1, 'the reply carries the voice flag too'); check('the advisor said something', ($ca['blocks'][0]['type'] ?? '') !== '' );
check('no audio is stored anywhere in the conversation', !str_contains($rows[$n0]['content'], 'audio') && !str_contains($rows[$n0 + 1]['content'], 'audio') && !str_contains($rows[$n0]['content'], 'base64'));
$hist = ai_history($vu); check('a voice turn is part of the normal conversation memory', str_contains(json_encode($hist), 'how am I doing with my bills'));
$rec = voice_recent($vu); check('the panel can list recent voice turns (what was said, what came back)', $rec && $rec[count($rec) - 1]['user'] === 'how am I doing with my bills' && $rec[count($rec) - 1]['reply'] !== '' || $rec[count($rec) - 1]['cards'] > 0);
$evs = []; ai_turn($vuu, 'typed question', $emit, []); check('a typed turn is unchanged: no deltas, no voice flag', !in_array('delta', array_column($evs, 'type'), true) && !str_contains((string) val("SELECT content FROM {ai_messages} WHERE user_id=? AND role='user' ORDER BY id DESC LIMIT 1", [$vu]), 'voice'));
load_demo_data($vu); $evs = []; ai_turn($vuu, 'show my spending by category', $emit, ['voice' => true, 'stream' => true]); $cards = array_filter($evs, fn($e) => $e['type'] === 'block' && ($e['block']['type'] ?? '') !== 'text'); check('rich results from a voice turn (tables, charts) still arrive as blocks for the panel', count($cards) >= 1);
$txBefore = (int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$vu]); $evs = []; ai_turn($vuu, 'add expense coffee', $emit, ['voice' => true, 'stream' => true]); $pv = array_values(array_filter($evs, fn($e) => $e['type'] === 'block' && ($e['block']['type'] ?? '') === 'preview')); check('a change proposed by voice is a preview that waits for Apply', $pv && $pv[0]['block']['status'] === 'proposed'); eq((int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$vu]), $txBefore, 'nothing was saved by the spoken request'); eq((string) val('SELECT status FROM {ai_actions} WHERE id=?', [$pv[0]['block']['action_id'] ?? 0]), 'proposed', 'the action is only proposed');
check('the voice hint tells the model to speak briefly and not to claim anything is saved', str_contains(ai_voice_hint(), 'SPOKEN_CONVERSATION') && str_contains(ai_voice_hint(), 'tap Apply'));
section('R5 voice: gates, budget, setup');
