eq($evs[0]['code'] ?? '', 'budget', 'over the monthly AI budget: the voice turn is refused with the same message as the chat'); eq((int) val('SELECT COUNT(*) FROM {ai_messages} WHERE user_id=?', [$vu]), $n1, 'and nothing is stored or spoken'); run('UPDATE {users} SET ai_budget_micro=NULL WHERE id=?', [$vu]);
set_setting('ai_enabled', '0'); $evs = []; ai_turn($vuu, 'hello', $emit, ['voice' => true]); eq($evs[0]['code'] ?? '', 'not_configured', 'advisor switched off: the gate speaks'); set_setting('ai_enabled', '1');
