section('R5 voice: speech-to-text and text-to-speech calls (local ElevenLabs stand-in)');
putenv('MFNC_VOICE_MOCK'); $elSrv = proc_open([PHP_BINARY, '-S', '127.0.0.1:8096', __DIR__ . '/elevenlabs_mock.php'], [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $elp5); $R5wait('127.0.0.1:8096'); @file_get_contents('http://127.0.0.1:8096/__reset');
putenv('ELEVENLABS_BASE=http://127.0.0.1:8096'); secret_set('el_key', 'test-el-key'); $cd5 = sys_get_temp_dir() . '/mfnc-voice-test-r5'; putenv('MFNC_VOICE_CACHE=' . $cd5); @array_map('unlink', glob($cd5 . '/mfnc-voice/*') ?: []); set_setting('feat_voice_mode', 'free'); set_setting('voice_enabled', '1'); set_setting('el_model', 'eleven_multilingual_v2'); run('DELETE FROM {c_voice_usage}');
