$a1 = voice_tts($vuu, 'Your rent is due on Friday.', 'voice'); eq($a1['engine'], 'elevenlabs', 'spoken replies use ElevenLabs when the person can'); eq($stt()['last_model'], 'eleven_flash_v2_5', 'with the low-latency model for the voice assistant'); $a2 = voice_tts($vuu, 'Your rent is due on Saturday.', 'web'); eq($stt()['last_model'], 'eleven_multilingual_v2', 'read-aloud elsewhere keeps the normal model');
check('the two models never share a cached file', voice_hash('x') !== voice_hash('x', 'mp3', 'eleven_flash_v2_5')); eq(voice_cfg()['fast_model'], 'eleven_flash_v2_5', 'the fast model is a setting (default flash v2.5)'); set_setting('el_model_fast', 'eleven_turbo_v2_5'); voice_tts($vuu, 'Another spoken sentence here.', 'voice'); eq($stt()['last_model'], 'eleven_turbo_v2_5', 'and the admin can change it'); set_setting('el_model_fast', 'eleven_flash_v2_5');
$tts0 = $stt()['tts']; $a3 = voice_tts($vuu, 'Your rent is due on Friday.', 'voice'); check('a repeated sentence comes from the cache (no second API call, nothing billed twice)', $a3['cached'] && $stt()['tts'] === $tts0);
eq((string) val("SELECT source FROM {c_voice_usage} WHERE user_id=? AND kind='tts' ORDER BY id LIMIT 1", [$vu]), 'voice', 'spoken replies are metered with source "voice"');
$marker = 'AUDIO-MARKER-' . bin2hex(random_bytes(12)); $audio = $marker . str_repeat('x', 4000); $s1 = voice_stt($vuu, $audio, 'audio/webm', 4, 'voice'); eq($s1['engine'], 'elevenlabs', 'speech-to-text through ElevenLabs'); eq($s1['text'], 'hello from the mock', 'returns the transcript'); eq((string) val("SELECT source FROM {c_voice_usage} WHERE user_id=? AND kind='stt' ORDER BY id DESC LIMIT 1", [$vu]), 'voice', 'STT is metered as voice usage');
$leak = false; foreach (array_merge(glob($cd5 . '/mfnc-voice/*') ?: [], glob(sys_get_temp_dir() . '/stt*') ?: []) as $f) { if (is_file($f) && str_contains((string) @file_get_contents($f), $marker)) { $leak = true; } } check('the recording is not kept on the server (no copy in the cache or the temp folder)', !$leak);
$tables = ['ai_messages', 'c_voice_usage']; $dump = ''; foreach ($tables as $t) { foreach (all('SELECT * FROM {' . $t . '} WHERE user_id=?', [$vu]) as $r) { $dump .= json_encode($r); } } check('...nor in the database (only transcripts and counters)', !str_contains($dump, $marker));
eq(voice_stt($vuu, '', 'audio/webm', 1, 'voice')['engine'], 'browser', 'empty audio: use the device recogniser'); set_setting('voice_daily_stt_sec', '1'); eq(voice_stt($vuu, $audio, 'audio/webm', 4, 'voice')['engine'], 'browser', 'over the daily listening limit: the device recogniser'); set_setting('voice_daily_stt_sec', '0');
