section('R5 assets: service worker, CSP-friendly loading, no inline handlers');
$sw = (string) file_get_contents(__DIR__ . '/../app/sw.js'); foreach (['ring.js', 'ring.css', 'accountmenu.js', 'accountmenu.css', 'voicedock.js', 'voicedock.css'] as $a) { check("$a is precached by the service worker", str_contains($sw, "/assets/$a") && is_file(__DIR__ . "/../assets/$a")); }
foreach (['ring.js', 'accountmenu.js', 'voicedock.js'] as $a) { $js = (string) file_get_contents(__DIR__ . "/../assets/$a"); check("$a has no eval, document.write or inline event attributes", !preg_match('/\beval\(|new Function\(|document\.write|\bon(click|error|load)\s*=\s*["\']/', $js)); }
check('raw audio never leaves the tab except to the speech-to-text endpoint (voicedock.js only POSTs blobs to /voice/stt)', substr_count((string) file_get_contents(__DIR__ . '/../assets/voicedock.js'), "base() + '/voice/stt'") === 1 && !str_contains((string) file_get_contents(__DIR__ . '/../assets/voicedock.js'), 'FormData'));
