else { foreach (['ring', 'voicedock', 'accountmenu'] as $jt) { $out = []; $rc = 0; exec(escapeshellarg($node) . ' ' . escapeshellarg(__DIR__ . "/js/$jt.test.js") . ' 2>&1', $out, $rc); $n = 0; foreach ($out as $l) { if (str_starts_with($l, 'ok - ')) { check("js $jt: " . substr($l, 5), true); $n++; } elseif (str_starts_with($l, 'FAIL - ')) { check("js $jt: " . substr($l, 7), false); } } check("js $jt: the test file ran (" . $n . ' checks) and exited cleanly', $rc === 0 && $n > 0, implode(' | ', array_slice($out, 0, 3))); } }
